        if item["sku"] == sku:
            return item
    return None


def stock_by_location(items: list[dict]) -> dict[str, int]:
    totals: dict[str, int] = {}
    for item in items:
        totals[item["location"]] = totals.get(item["location"], 0) + item["qty"]
    return totals


def bounds(values: list[int]) -> tuple[int, int]:
    return min(values), max(values)


