import base64
import inspect
from collections import OrderedDict
from collections.abc import Mapping


def arg_names(func):
    return inspect.getfullargspec(func).args


def encode(text):
    return base64.encodebytes(text.encode()).decode()


def decode(data):
    return base64.decodebytes(data.encode()).decode()


def merge(a, b):
    if not isinstance(a, Mapping) or not isinstance(b, Mapping):
        raise TypeError("expected mappings")
    merged = OrderedDict(a)
    merged.update(b)
    return merged

