import importlib

_CACHE: dict[str, object] = {}


def load(name: str) -> object | None:
    try:
        module = importlib.import_module(name)
    except ImportError:
        return None
    _CACHE[name] = module
    return module


def reload(name: str) -> object | None:
    module = _CACHE.get(name)
    if module is None:
        return None
    return importlib.reload(module)

